import numpy as np
def readxyz(p):
    lines = open(p).read().splitlines()
    n = int(lines[0]); els=[]; xyz=[]
    for l in lines[2:2+n]:
        t=l.split(); els.append(t[0]); xyz.append([float(x) for x in t[1:4]])
    return els, np.array(xyz)
els, xyz = readxyz("opt3.xyz")
pairs = [((47,46),"Sn-O(ester)"),((47,48),"Sn-N cov"),((47,54),"Sn->N dative"),((7,6),"B-O"),((41,5),"P-C4"),((41,42),"P=C2")]
for (i,j),name in pairs:
    print(name, round(np.linalg.norm(xyz[i]-xyz[j]),2))
EOF
